sys_script_include.script:
var HoCOHSGetChoiceValues = Class.create();

HoCOHSGetChoiceValues.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getChoiceValues: function() {
        var field = this.getParameter('field');
        var table = this.getParameter('table');
        var language = this.getParameter('language');
        var result = [];

        if (field && table) {
            var gr = new GlideRecord('sys_choice');

            gr.addQuery('element', field);
            gr.addQuery('name', table);
            gr.addQuery('language', language || 'en');
            gr.addQuery('inactive', false);
			gr.orderBy('sequence');
            gr.query();
            while (gr.next()) {
                result.push({
                    value: gr.value.toString(),
                    label: gr.label.toString()
                })
            }
            return JSON.stringify(result);

        }
        return JSON.stringify({});
    },

    type: 'HoCOHSGetChoiceValues'
});
